pub unsafe extern "C" fn vgic_mmio_read_group(vcpu: *mut kvm_vcpu, addr: gpa_t, len: u32) -> c_ulong {
    let intid = VGIC_ADDR_TO_INTID(addr, 1); let mut value: u32 = 0;
    for i in 0..(len * 8) { let irq = vgic_get_vcpu_irq(vcpu, intid + i); if (*irq).group { value |= 1 << i; } vgic_put_irq((*vcpu).kvm, irq); } value as c_ulong
}
unsafe fn vgic_update_vsgi(irq: *mut vgic_irq) { WARN_ON(its_prop_update_vsgi((*irq).host_irq, (*irq).priority, (*irq).group)); }
pub unsafe extern "C" fn vgic_mmio_write_group(vcpu:*mut kvm_vcpu,addr:gpa_t,len:u32,val:c_ulong) { let intid=VGIC_ADDR_TO_INTID(addr,1); let mut flags=0; for i in 0..len*8 { let irq=vgic_get_vcpu_irq(vcpu,intid+i); raw_spin_lock_irqsave(&mut (*irq).irq_lock,&mut flags); (*irq).group=(val & (1<<i))!=0; if (*irq).hw&&vgic_irq_is_sgi((*irq).intid) { vgic_update_vsgi(irq); raw_spin_unlock_irqrestore(&mut (*irq).irq_lock,flags); } else { vgic_queue_irq_unlock((*vcpu).kvm,irq,flags); } vgic_put_irq((*vcpu).kvm,irq); } }

pub unsafe extern "C" fn vgic_mmio_read_enable(vcpu:*mut kvm_vcpu,addr:gpa_t,len:u32)->c_ulong { let intid=VGIC_ADDR_TO_INTID(addr,1); let mut value=0u32; for i in 0..len*8 { let irq=vgic_get_vcpu_irq(vcpu,intid+i); if (*irq).enabled { value|=1<<i; } vgic_put_irq((*vcpu).kvm,irq); } value as c_ulong }
pub unsafe extern "C" fn vgic_mmio_write_senable(vcpu:*mut kvm_vcpu,addr:gpa_t,len:u32,val:c_ulong) { let intid=VGIC_ADDR_TO_INTID(addr,1); let mut flags=0; for i in 0..len*8 { if val&(1<<i)==0 {continue} let irq=vgic_get_vcpu_irq(vcpu,intid+i); raw_spin_lock_irqsave(&mut (*irq).irq_lock,&mut flags); if (*irq).hw&&vgic_irq_is_sgi((*irq).intid) { if !(*irq).enabled { (*irq).enabled=true; let data=&mut (*irq_to_desc((*irq).host_irq)).irq_data; while irqd_irq_disabled(data) { enable_irq((*irq).host_irq); } } raw_spin_unlock_irqrestore(&mut (*irq).irq_lock,flags); vgic_put_irq((*vcpu).kvm,irq); continue; } else if vgic_irq_is_mapped_level(irq) { let was_high=(*irq).line_level; (*irq).line_level=vgic_get_phys_line_level(irq); if !(*irq).active&&was_high&&!(*irq).line_level { vgic_irq_set_phys_active(irq,false); } } (*irq).enabled=true; vgic_queue_irq_unlock((*vcpu).kvm,irq,flags); vgic_put_irq((*vcpu).kvm,irq); } }
pub unsafe extern "C" fn vgic_mmio_write_cenable(vcpu:*mut kvm_vcpu,addr:gpa_t,len:u32,val:c_ulong) { let intid=VGIC_ADDR_TO_INTID(addr,1); let mut flags=0; for i in 0..len*8 { if val&(1<<i)==0 {continue} let irq=vgic_get_vcpu_irq(vcpu,intid+i); raw_spin_lock_irqsave(&mut (*irq).irq_lock,&mut flags); if (*irq).hw&&vgic_irq_is_sgi((*irq).intid)&&(*irq).enabled { disable_irq_nosync((*irq).host_irq); } (*irq).enabled=false; raw_spin_unlock_irqrestore(&mut (*irq).irq_lock,flags); vgic_put_irq((*vcpu).kvm,irq); } }
pub unsafe extern "C" fn vgic_uaccess_write_senable(vcpu:*mut kvm_vcpu,addr:gpa_t,len:u32,val:c_ulong)->i32 { let intid=VGIC_ADDR_TO_INTID(addr,1); let mut flags=0; for i in 0..len*8 {if val&(1<<i)==0{continue} let irq=vgic_get_vcpu_irq(vcpu,intid+i);raw_spin_lock_irqsave(&mut(*irq).irq_lock,&mut flags);(*irq).enabled=true;vgic_queue_irq_unlock((*vcpu).kvm,irq,flags);vgic_put_irq((*vcpu).kvm,irq);} 0 }
