unsafe fn __read_pending(vcpu:*mut kvm_vcpu,addr:gpa_t,len:u32,is_user:bool)->c_ulong { let intid=VGIC_ADDR_TO_INTID(addr,1);let mut value=0u32;for i in 0..len*8{let irq=vgic_get_vcpu_irq(vcpu,intid+i);let mut flags=0;let val;if (*irq).hw&&vgic_irq_is_sgi((*irq).intid){let mut p=false;let err=irq_get_irqchip_state((*irq).host_irq,IRQCHIP_STATE_PENDING,&mut p);WARN_RATELIMIT(err,"IRQ %d",(*irq).host_irq);val=p;}else if !is_user&&vgic_irq_is_mapped_level(irq){val=vgic_get_phys_line_level(irq);}else{val=if (*vcpu).kvm.arch.vgic.vgic_model==KVM_DEV_TYPE_ARM_VGIC_V3&&is_user{(*irq).pending_latch}else{irq_is_pending(irq)};}value|=(val as u32)<<i;raw_spin_unlock_irqrestore(&mut(*irq).irq_lock,flags);vgic_put_irq((*vcpu).kvm,irq);}value as c_ulong }
pub unsafe extern "C" fn vgic_mmio_read_pending(v:*mut kvm_vcpu,a:gpa_t,l:u32)->c_ulong{__read_pending(v,a,l,false)}
pub unsafe extern "C" fn vgic_uaccess_read_pending(v:*mut kvm_vcpu,a:gpa_t,l:u32)->c_ulong{__read_pending(v,a,l,true)}
unsafe fn is_vgic_v2_sgi(v:*mut kvm_vcpu,i:*mut vgic_irq)->bool{vgic_irq_is_sgi((*i).intid)&&(*v).kvm.arch.vgic.vgic_model==KVM_DEV_TYPE_ARM_VGIC_V2}
unsafe fn __set_pending(v:*mut kvm_vcpu,a:gpa_t,l:u32,val:c_ulong,user:bool){let id=VGIC_ADDR_TO_INTID(a,1);let mut f=0;for i in 0..l*8{if val&(1<<i)==0{continue}let q=vgic_get_vcpu_irq(v,id+i);if is_vgic_v2_sgi(v,q)&&!user{vgic_put_irq((*v).kvm,q);continue}raw_spin_lock_irqsave(&mut(*q).irq_lock,&mut f);if is_vgic_v2_sgi(v,q){(*q).source|=1<<(*v).vcpu_id;}if (*q).hw&&vgic_irq_is_sgi((*q).intid){let e=irq_set_irqchip_state((*q).host_irq,IRQCHIP_STATE_PENDING,true);WARN_RATELIMIT(e,"IRQ %d",(*q).host_irq);raw_spin_unlock_irqrestore(&mut(*q).irq_lock,f);vgic_put_irq((*v).kvm,q);continue}(*q).pending_latch=true;if (*q).hw&&!user{vgic_irq_set_phys_active(q,true)}vgic_queue_irq_unlock((*v).kvm,q,f);vgic_put_irq((*v).kvm,q)}}
pub unsafe extern "C" fn vgic_mmio_write_spending(v:*mut kvm_vcpu,a:gpa_t,l:u32,x:c_ulong){__set_pending(v,a,l,x,false)}
pub unsafe extern "C" fn vgic_uaccess_write_spending(v:*mut kvm_vcpu,a:gpa_t,l:u32,x:c_ulong)->i32{__set_pending(v,a,l,x,true);0}

unsafe fn vgic_hw_irq_cpending(_v:*mut kvm_vcpu,q:*mut vgic_irq){(*q).pending_latch=false;vgic_irq_set_phys_pending(q,false);if !(*q).active{vgic_irq_set_phys_active(q,false)}}
unsafe fn __clear_pending(v:*mut kvm_vcpu,a:gpa_t,l:u32,x:c_ulong,user:bool){let id=VGIC_ADDR_TO_INTID(a,1);let mut f=0;for i in 0..l*8{if x&(1<<i)==0{continue}let q=vgic_get_vcpu_irq(v,id+i);if is_vgic_v2_sgi(v,q)&&!user{vgic_put_irq((*v).kvm,q);continue}raw_spin_lock_irqsave(&mut(*q).irq_lock,&mut f);if is_vgic_v2_sgi(v,q){(*q).source=0}if (*q).hw&&vgic_irq_is_sgi((*q).intid){let e=irq_set_irqchip_state((*q).host_irq,IRQCHIP_STATE_PENDING,false);WARN_RATELIMIT(e,"IRQ %d",(*q).host_irq);raw_spin_unlock_irqrestore(&mut(*q).irq_lock,f);vgic_put_irq((*v).kvm,q);continue}if (*q).hw&&!user{vgic_hw_irq_cpending(v,q)}else{(*q).pending_latch=false}raw_spin_unlock_irqrestore(&mut(*q).irq_lock,f);vgic_put_irq((*v).kvm,q)}}
pub unsafe extern "C" fn vgic_mmio_write_cpending(v:*mut kvm_vcpu,a:gpa_t,l:u32,x:c_ulong){__clear_pending(v,a,l,x,false)}
pub unsafe extern "C" fn vgic_uaccess_write_cpending(v:*mut kvm_vcpu,a:gpa_t,l:u32,x:c_ulong)->i32{__clear_pending(v,a,l,x,true);0}

unsafe fn vgic_access_active_prepare(v:*mut kvm_vcpu,id:u32){if ((*v).kvm.arch.vgic.vgic_model==KVM_DEV_TYPE_ARM_VGIC_V3&&v!=kvm_get_running_vcpu())||id>=VGIC_NR_PRIVATE_IRQS{kvm_arm_halt_guest((*v).kvm)}}
unsafe fn vgic_access_active_finish(v:*mut kvm_vcpu,id:u32){if ((*v).kvm.arch.vgic.vgic_model==KVM_DEV_TYPE_ARM_VGIC_V3&&v!=kvm_get_running_vcpu())||id>=VGIC_NR_PRIVATE_IRQS{kvm_arm_resume_guest((*v).kvm)}}
unsafe fn __vgic_mmio_read_active(v:*mut kvm_vcpu,a:gpa_t,l:u32)->c_ulong{let id=VGIC_ADDR_TO_INTID(a,1);let mut x=0u32;for i in 0..l*8{let q=vgic_get_vcpu_irq(v,id+i);if(*q).active{x|=1<<i}vgic_put_irq((*v).kvm,q)}x as c_ulong}
pub unsafe extern "C" fn vgic_mmio_read_active(v:*mut kvm_vcpu,a:gpa_t,l:u32)->c_ulong{let id=VGIC_ADDR_TO_INTID(a,1);mutex_lock(&mut(*(*v).kvm).arch.config_lock);vgic_access_active_prepare(v,id);let x=__vgic_mmio_read_active(v,a,l);vgic_access_active_finish(v,id);mutex_unlock(&mut(*(*v).kvm).arch.config_lock);x}
pub unsafe extern "C" fn vgic_uaccess_read_active(v:*mut kvm_vcpu,a:gpa_t,l:u32)->c_ulong{__vgic_mmio_read_active(v,a,l)}

unsafe fn vgic_hw_irq_change_active(_v:*mut kvm_vcpu,q:*mut vgic_irq,active:bool,user:bool){if user{return}(*q).active=active;vgic_irq_set_phys_active(q,active)}
unsafe fn vgic_mmio_change_active(v:*mut kvm_vcpu,q:*mut vgic_irq,active:bool){let mut f=0;let req=kvm_get_running_vcpu();raw_spin_lock_irqsave(&mut(*q).irq_lock,&mut f);if(*q).hw&&!vgic_irq_is_sgi((*q).intid){vgic_hw_irq_change_active(v,q,active,req.is_null())}else if(*q).hw&&vgic_irq_is_sgi((*q).intid){(*q).active=false}else{let model=(*v).kvm.arch.vgic.vgic_model;(*q).active=active;let src=if !req.is_null(){(*req).vcpu_id}else{0};if model==KVM_DEV_TYPE_ARM_VGIC_V2&&active&&vgic_irq_is_sgi((*q).intid){(*q).active_source=src as u8}}if(*q).active{vgic_queue_irq_unlock((*v).kvm,q,f)}else{raw_spin_unlock_irqrestore(&mut(*q).irq_lock,f)}}
unsafe fn __vgic_mmio_write_cactive(v:*mut kvm_vcpu,a:gpa_t,l:u32,x:c_ulong){let id=VGIC_ADDR_TO_INTID(a,1);for i in 0..l*8{if x&(1<<i)==0{continue}let q=vgic_get_vcpu_irq(v,id+i);vgic_mmio_change_active(v,q,false);vgic_put_irq((*v).kvm,q)}}
pub unsafe extern "C" fn vgic_mmio_write_cactive(v:*mut kvm_vcpu,a:gpa_t,l:u32,x:c_ulong){let id=VGIC_ADDR_TO_INTID(a,1);mutex_lock(&mut(*(*v).kvm).arch.config_lock);vgic_access_active_prepare(v,id);__vgic_mmio_write_cactive(v,a,l,x);vgic_access_active_finish(v,id);mutex_unlock(&mut(*(*v).kvm).arch.config_lock)}
pub unsafe extern "C" fn vgic_mmio_uaccess_write_cactive(v:*mut kvm_vcpu,a:gpa_t,l:u32,x:c_ulong)->i32{__vgic_mmio_write_cactive(v,a,l,x);0}
unsafe fn __vgic_mmio_write_sactive(v:*mut kvm_vcpu,a:gpa_t,l:u32,x:c_ulong){let id=VGIC_ADDR_TO_INTID(a,1);for i in 0..l*8{if x&(1<<i)==0{continue}let q=vgic_get_vcpu_irq(v,id+i);vgic_mmio_change_active(v,q,true);vgic_put_irq((*v).kvm,q)}}
pub unsafe extern "C" fn vgic_mmio_write_sactive(v:*mut kvm_vcpu,a:gpa_t,l:u32,x:c_ulong){let id=VGIC_ADDR_TO_INTID(a,1);mutex_lock(&mut(*(*v).kvm).arch.config_lock);vgic_access_active_prepare(v,id);__vgic_mmio_write_sactive(v,a,l,x);vgic_access_active_finish(v,id);mutex_unlock(&mut(*(*v).kvm).arch.config_lock)}
