pub unsafe extern "C" fn vgic_mmio_read_priority(v:*mut kvm_vcpu,a:gpa_t,l:u32)->c_ulong{let id=VGIC_ADDR_TO_INTID(a,8);let mut x=0u64;for i in 0..l{let q=vgic_get_vcpu_irq(v,id+i);x|=((*q).priority as u64)<<(i*8);vgic_put_irq((*v).kvm,q)}x as c_ulong}
pub unsafe extern "C" fn vgic_mmio_write_priority(v:*mut kvm_vcpu,a:gpa_t,l:u32,x:c_ulong){let id=VGIC_ADDR_TO_INTID(a,8);let mut f=0;for i in 0..l{let q=vgic_get_vcpu_irq(v,id+i);raw_spin_lock_irqsave(&mut(*q).irq_lock,&mut f);(*q).priority=((x>>(i*8))&GENMASK(7,8-VGIC_PRI_BITS)) as u8;if(*q).hw&&vgic_irq_is_sgi((*q).intid){vgic_update_vsgi(q)}raw_spin_unlock_irqrestore(&mut(*q).irq_lock,f);vgic_put_irq((*v).kvm,q)}}
pub unsafe extern "C" fn vgic_mmio_read_config(v:*mut kvm_vcpu,a:gpa_t,l:u32)->c_ulong{let id=VGIC_ADDR_TO_INTID(a,2);let mut x=0u32;for i in 0..l*4{let q=vgic_get_vcpu_irq(v,id+i);if(*q).config==VGIC_CONFIG_EDGE{x|=2<<(i*2)}vgic_put_irq((*v).kvm,q)}x as c_ulong}
pub unsafe extern "C" fn vgic_mmio_write_config(v:*mut kvm_vcpu,a:gpa_t,l:u32,x:c_ulong){let id=VGIC_ADDR_TO_INTID(a,2);let mut f=0;for i in 0..l*4{if id+i<VGIC_NR_PRIVATE_IRQS{continue}let q=vgic_get_irq((*v).kvm,id+i);raw_spin_lock_irqsave(&mut(*q).irq_lock,&mut f);(*q).config=if x&(1<<(i*2+1))!=0{VGIC_CONFIG_EDGE}else{VGIC_CONFIG_LEVEL};raw_spin_unlock_irqrestore(&mut(*q).irq_lock,f);vgic_put_irq((*v).kvm,q)}}

pub unsafe extern "C" fn vgic_read_irq_line_level_info(v:*mut kvm_vcpu,id:u32)->u32{let n=(*v).kvm.arch.vgic.nr_spis+VGIC_NR_PRIVATE_IRQS;let mut x=0;for i in 0..32{if id+i<VGIC_NR_SGIS||id+i>=n{continue}let q=vgic_get_vcpu_irq(v,id+i);if(*q).config==VGIC_CONFIG_LEVEL&&(*q).line_level{x|=1<<i}vgic_put_irq((*v).kvm,q)}x}
pub unsafe extern "C" fn vgic_write_irq_line_level_info(v:*mut kvm_vcpu,id:u32,val:u32){let n=(*v).kvm.arch.vgic.nr_spis+VGIC_NR_PRIVATE_IRQS;let mut f=0;for i in 0..32{if id+i<VGIC_NR_SGIS||id+i>=n{continue}let q=vgic_get_vcpu_irq(v,id+i);let new=(val&(1<<i))!=0;raw_spin_lock_irqsave(&mut(*q).irq_lock,&mut f);(*q).line_level=new;if new{vgic_queue_irq_unlock((*v).kvm,q,f)}else{raw_spin_unlock_irqrestore(&mut(*q).irq_lock,f)}vgic_put_irq((*v).kvm,q)}}

unsafe extern "C" fn match_region(key:*const c_void,elt:*const c_void)->i32{let off=key as usize;let r=&*(elt as *const vgic_register_region);if off<r.reg_offset{-1}else if off>=r.reg_offset+r.len{1}else{0}}
pub unsafe extern "C" fn vgic_find_mmio_region(regions:*const vgic_register_region,n:i32,off:u32)->*const vgic_register_region{bsearch(&(off as usize) as*const _ as*const c_void,regions,n as usize,core::mem::size_of::<vgic_register_region>(),match_region)}
pub unsafe extern "C" fn vgic_set_vmcr(v:*mut kvm_vcpu,m:*mut vgic_vmcr){let d=&(*v).kvm.arch.vgic;match d.vgic_model{KVM_DEV_TYPE_ARM_VGIC_V5=>vgic_v5_set_vmcr(v,m),KVM_DEV_TYPE_ARM_VGIC_V3=>vgic_v3_set_vmcr(v,m),KVM_DEV_TYPE_ARM_VGIC_V2=>if static_branch_unlikely(&kvm_vgic_global_state.gicv3_cpuif){vgic_v3_set_vmcr(v,m)}else{vgic_v2_set_vmcr(v,m)},_=>BUG()}}
pub unsafe extern "C" fn vgic_get_vmcr(v:*mut kvm_vcpu,m:*mut vgic_vmcr){let d=&(*v).kvm.arch.vgic;match d.vgic_model{KVM_DEV_TYPE_ARM_VGIC_V5=>vgic_v5_get_vmcr(v,m),KVM_DEV_TYPE_ARM_VGIC_V3=>vgic_v3_get_vmcr(v,m),KVM_DEV_TYPE_ARM_VGIC_V2=>if static_branch_unlikely(&kvm_vgic_global_state.gicv3_cpuif){vgic_v3_get_vmcr(v,m)}else{vgic_v2_get_vmcr(v,m)},_=>BUG()}}

pub unsafe extern "C" fn vgic_data_mmio_bus_to_host(p:*const c_void,len:u32)->c_ulong{let d=kvm_mmio_read_buf(p,len);match len{1=>d,2=>le16_to_cpu(d),4=>le32_to_cpu(d),_=>le64_to_cpu(d)}}
pub unsafe extern "C" fn vgic_data_host_to_mmio_bus(p:*mut c_void,len:u32,mut d:c_ulong){match len{1=>{},2=>d=cpu_to_le16(d),4=>d=cpu_to_le32(d),_=>d=cpu_to_le64(d)}kvm_mmio_write_buf(p,len,d)}

unsafe fn check_region(k:*const kvm,r:*const vgic_register_region,a:gpa_t,len:i32)->bool{let flags=match len{1=>VGIC_ACCESS_8bit,4=>VGIC_ACCESS_32bit,8=>VGIC_ACCESS_64bit,_=>return false};let rr=&*r;if rr.access_flags&flags!=0&&IS_ALIGNED(a,len){if rr.bits_per_irq==0{return true}return VGIC_ADDR_TO_INTID(a,rr.bits_per_irq)<(*k).arch.vgic.nr_spis+VGIC_NR_PRIVATE_IRQS}false}
pub unsafe extern "C" fn vgic_get_mmio_region(v:*mut kvm_vcpu,i:*mut vgic_io_device,a:gpa_t,len:i32)->*const vgic_register_region{let r=vgic_find_mmio_region((*i).regions,(*i).nr_regions,a-(*i).base_addr);if r.is_null()||!check_region((*v).kvm,r,a,len){core::ptr::null()}else{r}}

unsafe fn kvm_to_vgic_iodev(d:*const kvm_io_device)->*mut vgic_io_device{container_of(d)}
unsafe fn vgic_uaccess_read(v:*mut kvm_vcpu,i:*mut vgic_io_device,a:gpa_t,x:*mut u32)->i32{let r=vgic_get_mmio_region(v,i,a,4);if r.is_null(){*x=0;return 0}let rv=if !(*i).redist_vcpu.is_null(){(*i).redist_vcpu}else{v};*x=if !(*r).uaccess_read.is_none(){(*r).uaccess_read.unwrap()(rv,a,4) as u32}else{((*r).read)(rv,a,4) as u32};0}
unsafe fn vgic_uaccess_write(v:*mut kvm_vcpu,i:*mut vgic_io_device,a:gpa_t,x:*const u32)->i32{let r=vgic_get_mmio_region(v,i,a,4);if r.is_null(){return 0}let rv=if !(*i).redist_vcpu.is_null(){(*i).redist_vcpu}else{v};if let Some(f)=(*r).uaccess_write{return f(rv,a,4,*x as c_ulong)}((*r).write)(rv,a,4,*x as c_ulong);0}
pub unsafe extern "C" fn vgic_uaccess(v:*mut kvm_vcpu,d:*mut vgic_io_device,w:bool,a:i32,x:*mut u32)->i32{if w{vgic_uaccess_write(v,d,a as gpa_t,x)}else{vgic_uaccess_read(v,d,a as gpa_t,x)}}
unsafe fn dispatch_mmio_read(v:*mut kvm_vcpu,d:*mut kvm_io_device,a:gpa_t,len:i32,out:*mut c_void)->i32{let i=kvm_to_vgic_iodev(d);let r=vgic_get_mmio_region(v,i,a,len);if r.is_null(){memset(out,0,len as usize);return 0}let data=match(*i).iodev_type{IODEV_CPUIF|IODEV_DIST=>(*r).read(v,a,len as u32),IODEV_REDIST=>(*r).read((*i).redist_vcpu,a,len as u32),IODEV_ITS=>(*r).its_read((*v).kvm,(*i).its,a,len as u32)};vgic_data_host_to_mmio_bus(out,len as u32,data);0}
unsafe fn dispatch_mmio_write(v:*mut kvm_vcpu,d:*mut kvm_io_device,a:gpa_t,len:i32,input:*const c_void)->i32{let i=kvm_to_vgic_iodev(d);let data=vgic_data_mmio_bus_to_host(input,len as u32);let r=vgic_get_mmio_region(v,i,a,len);if r.is_null(){return 0}match(*i).iodev_type{IODEV_CPUIF|IODEV_DIST=>(*r).write(v,a,len as u32,data),IODEV_REDIST=>(*r).write((*i).redist_vcpu,a,len as u32,data),IODEV_ITS=>(*r).its_write((*v).kvm,(*i).its,a,len as u32,data)};0}
pub static kvm_io_gic_ops:kvm_io_device_ops=kvm_io_device_ops{read:dispatch_mmio_read,write:dispatch_mmio_write};

pub unsafe extern "C" fn vgic_register_dist_iodev(k:*mut kvm,base:gpa_t,typ:vgic_type)->i32{let io=&mut(*k).arch.vgic.dist_iodev;let len=match typ{VGIC_V2=>vgic_v2_init_dist_iodev(io),VGIC_V3=>vgic_v3_init_dist_iodev(io),_=>{BUG();0}};io.base_addr=base;io.iodev_type=IODEV_DIST;io.redist_vcpu=core::ptr::null_mut();kvm_io_bus_register_dev(k,KVM_MMIO_BUS,base,len,&mut io.dev)}

